script:
let a = arch();
let pat = "";
let mnem = "svc";
let reg = "w8";
if a == "aarch64" { pat = "01 00 00 D4"; mnem = "svc"; reg = "w8"; }
else if a == "arm" { pat = "00 00 00 EF"; mnem = "svc"; reg = "r7"; }
else if a == "x86_64" { pat = "0F 05"; mnem = "syscall"; reg = "eax"; }
else if a == "x86" { pat = "CD 80"; mnem = "int"; reg = "eax"; }
if pat != "" {
  let hits = find_bytes(pat);
  for addr in hits {
    let chk = disasm(addr, 4);
    if chk.len() > 0 && chk[0].mnemonic == mnem && (a != "x86" || chk[0].op_str.contains("0x80")) {
      let nr = -1;
      if addr > 24 {
        let win = disasm(addr - 24, 24);
        for ins in win {
          if (ins.mnemonic == "mov" || ins.mnemonic == "movz") && (ins.op_str.starts_with(reg + ",") || (a == "aarch64" && ins.op_str.starts_with("x8,")) || (a == "x86_64" && ins.op_str.starts_with("rax,"))) {
            let parts = ins.op_str.split(",");
            if parts.len() >= 2 {
              let imm = parts[1];
              imm.trim();
              if imm.starts_with("#") { imm = imm.sub_string(1); }
              let is_hex = imm.starts_with("0x") || imm.starts_with("0X");
              if is_hex { imm = imm.sub_string(2); }
              let v = 0;
              let ok = imm.len() > 0;
              let base = if is_hex { 16 } else { 10 };
              imm.to_lower();
              let hex_digits = "0123456789abcdef";
              for ch in imm.chars() {
                let d = hex_digits.index_of(ch);
                if d < 0 || (!is_hex && d >= 10) { ok = false; break; }
                v = v * base + d;
              }
              if ok { nr = v; }
            }
          }
        }
      }
      let name = "";
      if a == "aarch64" {
        if nr == 48 { name = "faccessat"; }
        else if nr == 56 { name = "openat"; }
        else if nr == 57 { name = "close"; }
        else if nr == 63 { name = "read"; }
        else if nr == 78 { name = "readlinkat"; }
        else if nr == 79 { name = "newfstatat"; }
        else if nr == 93 { name = "exit"; }
        else if nr == 94 { name = "exit_group"; }
        else if nr == 117 { name = "ptrace"; }
        else if nr == 129 { name = "kill"; }
        else if nr == 130 { name = "tkill"; }
        else if nr == 131 { name = "tgkill"; }
        else if nr == 167 { name = "prctl"; }
        else if nr == 172 { name = "getpid"; }
        else if nr == 174 { name = "getuid"; }
        else if nr == 198 { name = "socket"; }
        else if nr == 203 { name = "connect"; }
        else if nr == 220 { name = "clone"; }
        else if nr == 221 { name = "execve"; }
        else if nr == 222 { name = "mmap"; }
        else if nr == 226 { name = "mprotect"; }
        else if nr == 279 { name = "memfd_create"; }
      } else if a == "x86_64" {
        if nr == 0 { name = "read"; }
        else if nr == 3 { name = "close"; }
        else if nr == 9 { name = "mmap"; }
        else if nr == 10 { name = "mprotect"; }
        else if nr == 39 { name = "getpid"; }
        else if nr == 56 { name = "clone"; }
        else if nr == 59 { name = "execve"; }
        else if nr == 60 { name = "exit"; }
        else if nr == 62 { name = "kill"; }
        else if nr == 101 { name = "ptrace"; }
        else if nr == 157 { name = "prctl"; }
        else if nr == 231 { name = "exit_group"; }
        else if nr == 257 { name = "openat"; }
        else if nr == 269 { name = "faccessat"; }
        else if nr == 319 { name = "memfd_create"; }
      } else if a == "arm" || a == "x86" {
        if nr == 1 { name = "exit"; }
        else if nr == 3 { name = "read"; }
        else if nr == 6 { name = "close"; }
        else if nr == 11 { name = "execve"; }
        else if nr == 20 { name = "getpid"; }
        else if nr == 26 { name = "ptrace"; }
        else if nr == 37 { name = "kill"; }
        else if nr == 120 { name = "clone"; }
        else if nr == 125 { name = "mprotect"; }
        else if nr == 172 { name = "prctl"; }
        else if nr == 192 { name = "mmap2"; }
        else if nr == 248 { name = "exit_group"; }
        else if nr == 322 { name = "openat"; }
        else if nr == 334 { name = "faccessat"; }
      }
      let title = if name != "" { "Direct Syscall: " + name + " (" + nr + ")" } else if nr >= 0 { "Direct Syscall #" + nr } else { "Direct Syscall (" + mnem + ")" };
      let sev = if name == "ptrace" || name == "kill" || name == "tgkill" || name == "tkill" || name == "prctl" { "HIGH" } else { "MEDIUM" };
      if name == "kill" || name == "tgkill" || name == "tkill" || name == "exit" || name == "exit_group" {
        report_patch(title, addr, sev, chk[0].mnemonic + " " + chk[0].op_str, "quick", "nop", 0);
      } else {
        report(title, addr, sev, chk[0].mnemonic + " " + chk[0].op_str);
      }
    }
  }
}
